-- READ-ONLY. December 2026 gate, section 5: data and content integrity audit. Counts only (no names, emails or other personal data are selected).
-- Run on Preview (scrubbed or test data) and, because it only reads, on Production:   run_readonly_sql.ps1 -Target Preview|Production -File <this file>
-- Every row is "check | rows found | what it means". 0 is the passing value unless the check says otherwise. Row ids can be listed with the same condition in a restricted session.
\pset format unaligned
\pset null '(none)'
select '--- A. Schools, classes, enrolments' as section;
select 'A1 classes whose teacher profile no longer exists' as chk, count(*) as n, 'orphaned class' as meaning from public.classes c where c.primary_teacher_id is not null and not exists (select 1 from public.teacher_profiles t where t.id = c.primary_teacher_id)
union all select 'A2 active enrolments whose class or learner no longer exists', count(*), 'orphaned enrolment' from public.class_memberships m where m.status::text = 'active' and (not exists (select 1 from public.classes c where c.id = m.class_id) or not exists (select 1 from public.student_profiles s where s.id = m.student_id))
union all select 'A3 learners with more than one active enrolment in the same class', count(*), 'duplicate active enrolment' from (select class_id, student_id from public.class_memberships where status::text = 'active' group by 1, 2 having count(*) > 1) d
union all select 'A4 active enrolments in an archived class', count(*), 'learner still enrolled in archived class' from public.class_memberships m join public.classes c on c.id = m.class_id where m.status::text = 'active' and c.status::text = 'archived'
union all select 'A5 classes whose grade does not match their curriculum grade list (grade_code empty)', count(*), 'class without a grade code' from public.classes c where c.status::text = 'active' and coalesce(nullif(c.grade_code, ''), '') = ''
union all select 'A6 learners enrolled in a class of a different level than their own', count(*), 'level mismatch (informational: older joins before the level check)' from public.class_memberships m join public.classes c on c.id = m.class_id join public.student_profiles s on s.id = m.student_id where m.status::text = 'active' and s.grade_code is not null and c.grade_code is not null and upper(s.grade_code) <> upper(c.grade_code) and not (s.grade_code = 'B10' and c.grade_code = 'SHS1');
select '--- B. Attempts and results' as section;
select 'B1 attempts with no owner (no learner user)' as chk, count(*) as n, 'ownerless attempt' as meaning from public.attempts where student_user_id is null
union all select 'B2 attempts whose learner profile does not match the owner user', count(*), 'owner mismatch' from public.attempts a join public.student_profiles s on s.id = a.student_id where s.user_id is distinct from a.student_user_id
union all select 'B3 attempts on an assignment of a class the learner is not (or was never) a member of', count(*), 'attempt outside enrolment' from public.attempts a where a.class_id is not null and not exists (select 1 from public.class_memberships m where m.class_id = a.class_id and m.student_user_id = a.student_user_id)
union all select 'B4 more than one in-progress attempt for the same learner and assessment', count(*), 'duplicate open attempt' from (select assessment_id, student_id from public.attempts where status = 'in_progress' group by 1, 2 having count(*) > 1) d
union all select 'B5 submitted attempts with no result row', count(*), 'submitted without result' from public.attempts a where a.status = 'submitted' and a.assignment_id is not null and not exists (select 1 from public.assessment_results r where r.attempt_id = a.id)
union all select 'B6 attempts counted twice in results (same attempt, more than one result)', count(*), 'duplicate result' from (select attempt_id from public.assessment_results where attempt_id is not null group by 1 having count(*) > 1) d
union all select 'B7 attempts that exceed the assessment attempt limit', count(*), 'limit exceeded' from (select a.assessment_id, a.student_id, count(*) c, max(s.max_attempts) m from public.attempts a join public.assessments s on s.id = a.assessment_id group by 1, 2) x where c > greatest(coalesce(m, 1), 1)
union all select 'B8 reward rows twice for the same attempt and reason', count(*), 'duplicate reward' from (select attempt_id, reason from public.xp_transactions group by 1, 2 having count(*) > 1) d
union all select 'B9 completion rewards on attempts with nothing answered (before 20261120120000; may be non-zero in history)', count(*), 'history only: new ones are no longer created' from public.xp_transactions x join public.attempts a on a.id = x.attempt_id where x.reason = 'ASSIGNMENT_COMPLETION' and coalesce(a.answered_count, 0) = 0;
select '--- C. Content: what learners can be served' as section;
select 'C1 active questions that are not approved' as chk, count(*) as n, 'unapproved question served' as meaning from public.questions where status::text = 'active' and lower(coalesce(validation_status, '')) not in ('approved', 'validated')
union all select 'C2 active approved questions with no reviewer or review time', count(*), 'approval provenance missing' from public.questions where status::text = 'active' and lower(coalesce(validation_status, '')) in ('approved', 'validated') and (reviewed_by is null or reviewed_at is null)
union all select 'C3 active questions without a correct answer', count(*), 'no correct answer' from public.questions where status::text = 'active' and coalesce(nullif(trim(correct_answer), ''), '') = '' and answer_spec is null
union all select 'C4 active single-choice questions whose correct answer is not one of A to D', count(*), 'correct answer outside options' from public.questions where status::text = 'active' and answer_type = 'SINGLE_CHOICE' and upper(trim(coalesce(correct_answer, ''))) not in ('A', 'B', 'C', 'D')
union all select 'C5 active single-choice questions with an empty option', count(*), 'blank option' from public.questions where status::text = 'active' and answer_type = 'SINGLE_CHOICE' and (coalesce(nullif(trim(option_a), ''), '') = '' or coalesce(nullif(trim(option_b), ''), '') = '' or coalesce(nullif(trim(option_c), ''), '') = '' or coalesce(nullif(trim(option_d), ''), '') = '')
union all select 'C6 active questions with an empty explanation', count(*), 'no feedback' from public.questions where status::text = 'active' and coalesce(nullif(trim(explanation), ''), '') = ''
union all select 'C7 active questions with no curriculum topic', count(*), 'untraceable to indicator' from public.questions where status::text = 'active' and curriculum_node_id is null
union all select 'C8 active questions whose grade differs from their topic grade', count(*), 'grade mismatch' from public.questions q join public.curriculum_nodes n on n.id = q.curriculum_node_id where q.status::text = 'active' and q.canonical_grade_code is not null and n.canonical_grade_code is not null and q.canonical_grade_code <> n.canonical_grade_code
union all select 'C9 sets of active questions with identical text (duplicate content)', count(*), 'duplicate groups' from (select text_hash from public.questions where status::text = 'active' and text_hash is not null group by 1 having count(*) > 1) d
union all select 'C10 questions inside published assignments that are no longer active or approved (withdrawn after assignment)', count(*), 'withdrawn content still assigned' from public.assessment_questions aq join public.questions q on q.id = aq.question_id join public.assessments s on s.id = aq.assessment_id where s.opens_at is not null and (q.status::text <> 'active' or lower(coalesce(q.validation_status, '')) not in ('approved', 'validated')) and exists (select 1 from public.assignments a where a.assessment_id = s.id and a.status::text = 'published');
select '--- D. Access, grants and guardian links' as section;
select 'D1 active subscriptions already past their end date' as chk, count(*) as n, 'stale grant still marked active' as meaning from public.learner_subscriptions where status = 'active' and valid_until < now()
union all select 'D2 pilot or manual grants without a note or creator', count(*), 'unaudited grant' from public.learner_subscriptions where source = 'manual' and (coalesce(nullif(trim(note), ''), '') = '' or created_by is null)
union all select 'D3 grants longer than 731 days', count(*), 'unbounded grant' from public.learner_subscriptions where valid_until - valid_from > interval '731 days'
union all select 'D4 guardian links active without the learner or staff agreeing (consent not granted)', count(*), 'link without authorisation' from public.account_relationships where family_workspace_id is not null and status = 'active' and consent_status not in ('granted', 'not_required')
union all select 'D5 guardian links active with no verifier recorded', count(*), 'link without verifier' from public.account_relationships where family_workspace_id is not null and status = 'active' and verified_by is null
union all select 'D6 guardian links pointing at a non-adult account', count(*), 'link from a learner account' from public.account_relationships r join public.profiles p on p.id = r.source_user_id where r.family_workspace_id is not null and lower(p.role::text) = 'student'
union all select 'D7 managed under-13 learners with no consent record', count(*), 'managed child without consent' from public.student_profiles sp where sp.managed_by is not null and sp.is_minor and sp.erased_at is null and not exists (select 1 from public.learner_consent c where c.user_id = sp.user_id and c.status in ('granted', 'not_required'));
